export class ConfError extends Error {}
export class Table { constructor() { this.map = new Map(); this.header = false } }
export class ArrayNode { constructor(aot) { this.items = []; this.aot = aot } }

const fail = m => { throw new ConfError(m) }
const isWs = c => c === ' ' || c === '\t'
const isNameChar = c => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)

class LineParser {
  constructor(s) { this.s = s; this.i = 0 }
  get c() { return this.s[this.i] }
  ws() { while (isWs(this.c)) this.i++ }
  atEnd() { return this.i >= this.s.length || this.c === '#' || this.c === ';' }

  str(q) {
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= this.s.length) fail('unterminated string')
      const ch = this.c
      if (ch === q) { this.i++; return out }
      if (q === "'" || ch !== '\\') { out += ch; this.i++; continue }
      this.i++
      if (this.i >= this.s.length) fail('unterminated string')
      const e = this.c
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (e in map) { out += map[e]; this.i++ } else if (e === 'u') {
        const h = this.s.slice(this.i + 1, this.i + 5)
        if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16)); this.i += 5
      } else fail(`invalid escape \\${String.fromCodePoint(this.s.codePointAt(this.i))}`)
    }
  }

  name() {
    const c = this.c
    if (c === '"' || c === "'") return this.str(c)
    const st = this.i
    while (isNameChar(this.c)) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.c !== '.') { this.i = save; this.ws(); return parts }
      this.i++
      this.ws()
      parts.push(this.name())
    }
  }

  value(path) {
    this.ws()
    const c = this.c
    if (this.atEnd() || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { type: 'string', value: this.str(c) }
    if (c === '[') return this.array(path)
    if (c === '{') return this.inline(path)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.c) && !',]};'.includes(this.c)) this.i++
    const t = this.s.slice(st, this.i)
    if (t === 'true') return { type: 'boolean', value: true }
    if (t === 'false') return { type: 'boolean', value: false }
    const D = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${D}$`).test(t)) return { type: 'integer', value: BigInt(t.replace(/_/g, '')) }
    if (new RegExp(`^[+-]?${D}(?:\\.${D})?(?:[eE][+-]?${D})?$`).test(t)) return { type: 'float', value: Number(t.replace(/_/g, '')) }
    return fail(`invalid value ${t}`)
  }

  array(path) {
    this.i++
    const a = new ArrayNode(false)
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ']') { this.i++; return a }
      a.items.push(this.value(path + '[' + a.items.length + ']'))
      this.ws()
      if (this.c === ',') { this.i++; continue }
      if (this.c === ']') { this.i++; return a }
      if (this.atEnd()) fail('unterminated array')
      fail('trailing text after a value')
    }
  }

  inline(path) {
    this.i++
    const t = new Table()
    this.ws()
    if (this.c === '}') { this.i++; return t }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const names = this.dotted()
      if (this.c !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value(path)
      assign(t, names, v, path)
      this.ws()
      if (this.c === ',') { this.i++; continue }
      if (this.c === '}') { this.i++; return t }
      if (this.atEnd()) fail('unterminated inline table')
      fail('trailing text after a value')
    }
  }
}

const join = (base, names) => (base ? [base, ...names] : names).join('.')

function walk(t, names, base, create = true) {
  let cur = t
  for (let k = 0; k < names.length; k++) {
    let n = cur.map.get(names[k])
    if (n === undefined) { n = new Table(); cur.map.set(names[k], n) }
    if (n instanceof ArrayNode && n.aot) n = n.items[n.items.length - 1]
    if (!(n instanceof Table)) fail(`${join(base, names.slice(0, k + 1))} is not a table`)
    cur = n
  }
  return cur
}

function assign(t, names, v, base) {
  const parent = walk(t, names.slice(0, -1), base)
  const last = names[names.length - 1]
  if (parent.map.has(last)) fail(`key ${join(base, names)} is defined twice`)
  parent.map.set(last, v)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = new Table()
  let cur = root
  let curPath = ''
  lines.forEach((line, idx) => {
    const p = new LineParser(line)
    try {
      p.ws()
      if (p.i >= line.length || p.c === '#' || p.c === ';') return
      if (p.c === '[') {
        p.i++
        const dbl = p.c === '['
        if (dbl) p.i++
        p.ws()
        const names = p.dotted()
        const close = dbl ? ']]' : ']'
        if (line.slice(p.i, p.i + close.length) !== close) fail('unterminated table header')
        p.i += close.length
        p.ws()
        if (!p.atEnd()) fail('trailing text after a table header')
        const full = names.join('.')
        const parent = walk(root, names.slice(0, -1), '')
        const last = names[names.length - 1]
        const ex = parent.map.get(last)
        if (!dbl) {
          if (ex === undefined) { cur = new Table(); cur.header = true; parent.map.set(last, cur) }
          else if (ex instanceof Table) {
            if (ex.header) fail(`table ${full} is defined twice`)
            ex.header = true; cur = ex
          } else fail(`${full} is not a table`)
        } else {
          let arr = ex
          if (ex === undefined) { arr = new ArrayNode(true); parent.map.set(last, arr) }
          else if (!(ex instanceof ArrayNode && ex.aot)) fail(`${full} is not an array of tables`)
          cur = new Table(); cur.header = true
          arr.items.push(cur)
        }
        curPath = full
        return
      }
      const names = p.dotted()
      if (p.c !== '=') fail('expected key = value')
      p.i++
      const v = p.value(join(curPath, names))
      p.ws()
      if (!p.atEnd()) fail('trailing text after a value')
      assign(cur, names, v, curPath)
    } catch (e) {
      if (e instanceof ConfError) e.message = `line ${idx + 1}: ${e.message}`
      throw e
    }
  })
  return root
}
